def merge(intervals):
    """Return sorted, disjoint, merged intervals covering the same points."""
    parsed = []
    for iv in intervals:
        s, e = _validate(iv)
        if s < e:
            parsed.append((s, e))
    if not parsed:
        return []
    parsed.sort()
    merged = [parsed[0]]
    for s, e in parsed[1:]:
        last_s, last_e = merged[-1]
        if s <= last_e:
            if e > last_e:
                merged[-1] = (last_s, e)
        else:
            merged.append((s, e))
    return merged


def subtract(a, b):
    """Return points in a that are not in b, as merged sorted intervals."""
    a = merge(a)
    b = merge(b)
    if not a:
        return []
    if not b:
        return a
    result = []
    i = 0
    for s, e in a:
        cur_s, cur_e = s, e
        while i < len(b) and b[i][1] <= cur_s:
            i += 1
        while i < len(b) and b[i][0] < cur_e:
            bs, be = b[i]
            if bs > cur_s:
                result.append((cur_s, bs))
            if be >= cur_e:
                cur_s = cur_e
                break
            cur_s = max(cur_s, be)
            i += 1
        if cur_s < cur_e:
            result.append((cur_s, cur_e))
    return merge(result)


def total_length(intervals):
    """Return total length covered by the union of intervals."""
