def render(template, values):
    if not isinstance(template, str):
        raise TypeError("template must be str")

    n = len(template)
    out = []
    i = 0

    def is_valid_key(k):
        if not k:
            return False
        parts = k.split('.')
        for part in parts:
            if not part:
                return False
            if not part[0].isalpha() and part[0] != '_':
                return False
            if not all(c.isalnum() or c == '_' for c in part):
                return False
        return True

    def lookup(k):
        parts = k.split('.')
        cur = values
        for part in parts:
            if not isinstance(cur, dict) or part not in cur:
                return None
            cur = cur[part]
        return cur

    while i < n:
        ch = template[i]
        if ch == '\\':
            if i + 1 < n:
                nxt = template[i + 1]
                if nxt == '\\':
                    out.append('\\')
                    i += 2
                    continue
                elif nxt == '{':
                    out.append('{')
                    i += 2
                    continue
                else:
                    out.append('\\')
                    i += 1
                    continue
            else:
                out.append('\\')
                i += 1
                continue
        elif ch == '{':
            if i + 1 < n and template[i + 1] == '{':
                # placeholder
                start = i
                i += 2
                end = template.find('}}', i)
                if end == -1:
                    raise ValueError(f"unclosed placeholder at {start}")
                content = template[i:end]
                pipe_pos = content.find('|')
                if pipe_pos == -1:
                    key_part = content
                    default_part = None
                else:
                    key_part = content[:pipe_pos]
                    default_part = content[pipe_pos + 1:]
                key = key_part.strip(' ')
                if not is_valid_key(key):
                    raise ValueError(f"bad key: {key}")
                val = lookup(key)
                if val is None:
                    if default_part is not None:
                        out.append(default_part.strip(' '))
                    else:
                        raise KeyError(f"missing: {key}")
                else:
                    if val is True:
                        out.append('true')
                    elif val is False:
                        out.append('false')
                    else:
                        out.append(str(val))
                i = end + 2
                continue
            else:
                out.append('{')
                i += 1
                continue
        else:
            out.append(ch)
            i += 1

    return ''.join(out)
