def parse_ini(text):
    result = {}
    current_section = ''
    current_key = None
    current_value = None
    lines = text.split('\n')

    for i, raw_line in enumerate(lines, start=1):
        line = raw_line
        if line.endswith('\r'):
            line = line[:-1]

        # Rule 1: blank or whitespace-only line
        if line.strip() == '':
            current_key = None
            current_value = None
            continue

        # Rule 2: comment line (first non-whitespace is ; or #)
        stripped_leading = line.lstrip()
        if stripped_leading and stripped_leading[0] in ';#':
            continue

        # Rule 3: continuation line (starts with space or tab)
        if line and line[0] in ' \t':
            if current_key is None:
                raise ValueError(f'line {i}: continuation without key')
            stripped = line.strip()
            if current_value == '':
                current_value = stripped
            else:
                current_value = current_value + ' ' + stripped
            result[current_section][current_key] = current_value
            continue

        # Rule 4: section header
        stripped = line.strip()
        if stripped.startswith('[') and stripped.endswith(']'):
            section_name = stripped[1:-1].strip().lower()
            current_section = section_name
            current_key = None
            current_value = None
            if current_section not in result:
                result[current_section] = {}
            continue

        # Rule 5: key-value line
        if '=' not in line:
            raise ValueError(f'line {i}: missing =')
        key_part, value_part = line.split('=', 1)
        key = key_part.strip().lower()
        value = value_part.strip()
        if key == '':
            raise ValueError(f'line {i}: empty key')

        if current_section not in result:
            result[current_section] = {}

        if key in result[current_section]:
            raise ValueError(f'duplicate key {key!r} in section {current_section!r}')

        result[current_section][key] = value
        current_key = key
        current_value = value

    # Rule 6: strip one pair of quotes from values of at least two chars
    for section in result:
        for key in result[section]:
            v = result[section][key]
            if len(v) >= 2 and v.startswith('"') and v.endswith('"'):
                result[section][key] = v[1:-1]

    return result
