import copy


def escape_token(token):
    return token.replace('~', '~0').replace('/', '~1')


def _decode_pointer(pointer):
    if pointer == '':
        return []
    if not pointer.startswith('/'):
        raise ValueError("Non-empty pointer must start with '/'")
    tokens = pointer[1:].split('/')
    decoded = []
    for token in tokens:
        decoded_token = []
        i = 0
        while i < len(token):
            ch = token[i]
            if ch != '~':
                decoded_token.append(ch)
                i += 1
                continue
            # ch is '~'
            if i + 1 >= len(token):
                raise ValueError("Unescaped '~' at end of token")
            nxt = token[i + 1]
            if nxt == '0':
                decoded_token.append('~')
            elif nxt == '1':
                decoded_token.append('/')
            else:
                raise ValueError("Invalid escape sequence in token")
            i += 2
        decoded.append(''.join(decoded_token))
    return decoded


def resolve(doc, pointer):
    tokens = _decode_pointer(pointer)
    current = doc
    for token in tokens:
        if isinstance(current, dict):
            if token not in current:
                raise KeyError(token)
            current = current[token]
        elif isinstance(current, list):
            if token == '-':
                raise KeyError(token)
            if not token.isdigit():
                raise KeyError(token)
            if token != '0' and token.startswith('0'):
                raise KeyError(token)
            idx = int(token)
            if idx < 0 or idx >= len(current):
                raise KeyError(token)
            current = current[idx]
        else:
            raise KeyError(token)
    return current


def set_value(doc, pointer, value):
    new_doc = copy.deepcopy(doc)
    if pointer == '':
        return value
    tokens = _decode_pointer(pointer)
    current = new_doc
    for token in tokens[:-1]:
        if isinstance(current, dict):
            if token not in current:
                raise KeyError(token)
            current = current[token]
        elif isinstance(current, list):
            if token == '-':
                raise KeyError(token)
            if not token.isdigit():
                raise KeyError(token)
            if token != '0' and token.startswith('0'):
                raise KeyError(token)
            idx = int(token)
            if idx < 0 or idx >= len(current):
                raise KeyError(token)
            current = current[idx]
        else:
            raise KeyError(token)
    last_token = tokens[-1]
    if isinstance(current, dict):
        current[last_token] = value
    elif isinstance(current, list):
        if last_token == '-':
            current.append(value)
        elif last_token.isdigit() and (last_token == '0' or not last_token.startswith('0')):
            idx = int(last_token)
            if idx < 0 or idx > len(current):
                raise KeyError(last_token)
            if idx == len(current):
                current.append(value)
            else:
                current[idx] = value
        else:
            raise KeyError(last_token)
    else:
        raise KeyError(last_token)
    return new_doc
