def wrap_text(text, width):
    if not isinstance(width, int) or width < 2:
        raise ValueError("width must be an int >= 2")
    words = text.split()
    if not words:
        return []
    lines = []
    current = ""
    for word in words:
        if len(word) <= width:
            # Normal word: append to current line if it fits.
            if current == "":
                candidate = word
            else:
                candidate = current + " " + word
            if len(candidate) <= width:
                current = candidate
                continue
            else:
                lines.append(current)
                current = word
        else:
            # Long word: finish current line first, then split the word.
            if current != "":
                lines.append(current)
                current = ""
            chunk_len = width - 1
            remaining = word
            while len(remaining) > width:
                lines.append(remaining[:chunk_len] + "-")
                remaining = remaining[chunk_len:]
            current = remaining
    if current != "":
        lines.append(current)
    return lines
