from collections import deque
from math import isnan


def _validate_limit(limit):
    if isinstance(limit, bool):
        raise ValueError("limit must not be bool")
    if not isinstance(limit, (int, float)):
        raise ValueError("limit must be int or float")
    if isnan(limit):
        raise ValueError("limit must not be NaN")
    if limit < 0:
        raise ValueError("limit must be >= 0")


def _validate_value(x):
    if isinstance(x, bool):
        raise TypeError("values must contain int or float, not bool")
    if not isinstance(x, (int, float)):
        raise TypeError("values must contain int or float")
    if isinstance(x, float) and isnan(x):
        raise ValueError("values must not contain NaN")


def _validate_values(values):
    for x in values:
        _validate_value(x)


def _range_width(mono_max, mono_min):
    return mono_max[0] - mono_min[0]


def longest_calm(values, limit):
    _validate_limit(limit)

    n = len(values)
    if n == 0:
        return (0, 0)

    _validate_values(values)

    best_len = 1
    best_i = 0

    mono_max = deque()
    mono_min = deque()
    left = 0

    for right in range(n):
        x = values[right]

        while mono_max and mono_max[-1][0] <= x:
            mono_max.pop()
        mono_max.append((x, right))

        while mono_min and mono_min[-1][0] >= x:
            mono_min.pop()
        mono_min.append((x, right))

        while left <= right and _range_width(mono_max, mono_min) > limit:
            if mono_max[0][1] == left:
                mono_max.popleft()
            if mono_min[0][1] == left:
                mono_min.popleft()
            left += 1

        window_len = right - left + 1
        if window_len > best_len:
            best_len = window_len
            best_i = left

    return (best_i, best_i + best_len)


def count_calm(values, limit):
    _validate_limit(limit)

    n = len(values)
    if n == 0:
        return 0

    _validate_values(values)

    mono_max = deque()
    mono_min = deque()
    left = 0
    total = 0

    for right in range(n):
        x = values[right]

        while mono_max and mono_max[-1][0] <= x:
            mono_max.pop()
        mono_max.append((x, right))

        while mono_min and mono_min[-1][0] >= x:
            mono_min.pop()
        mono_min.append((x, right))

        while left <= right and _range_width(mono_max, mono_min) > limit:
            if mono_max[0][1] == left:
                mono_max.popleft()
            if mono_min[0][1] == left:
                mono_min.popleft()
            left += 1

        total += right - left + 1

    return total
