import heapq
from typing import Any


class MedianTracker:
    def __init__(self, prefer_high: bool = False) -> None:
        self.prefer_high = prefer_high

        # max-heap for the lower half (stores negatives of values)
        self._low: list[int] = []
        # min-heap for the higher half
        self._high: list[int] = []

        # delayed deletions
        self._delayed_low: dict[int, int] = {}
        self._delayed_high: dict[int, int] = {}

        self._low_size = 0  # effective size of low half
        self._high_size = 0  # effective size of high half
        self._total = 0

    def _validate_int(self, x: Any) -> int:
        if isinstance(x, bool) or not isinstance(x, int):
            raise TypeError("value must be an int")
        return x

    def add(self, x: Any) -> None:
        x = self._validate_int(x)

        if not self._low or x <= -self._low[0]:
            heapq.heappush(self._low, -x)
            self._low_size += 1
        else:
            heapq.heappush(self._high, x)
            self._high_size += 1

        self._total += 1
        self._rebalance()

    def remove(self, x: Any) -> None:
        x = self._validate_int(x)

        if self._total == 0:
            raise ValueError("not present")

        low_top = -self._low[0] if self._low else None
        if x <= low_top:
            if x not in self._delayed_low and (not self._low or x > low_top):
                raise ValueError("not present")
            self._delayed_low[x] = self._delayed_low.get(x, 0) + 1
            self._low_size -= 1
        else:
            if x not in self._delayed_high and (not self._high or x < self._high[0]):
                raise ValueError("not present")
            self._delayed_high[x] = self._delayed_high.get(x, 0) + 1
            self._high_size -= 1

        self._total -= 1
        self._rebalance()
        self._prune_tops()

    def median(self) -> int:
        if self._total == 0:
            raise LookupError("median is undefined for empty tracker")

        self._prune_tops()

        if self._total % 2 == 1:
            # odd: top of the larger half
            if self._low_size > self._high_size:
                return -self._low[0]
            else:
                return self._high[0]
        else:
            # even
            if self.prefer_high:
                return self._high[0]
            else:
                return -self._low[0]

    def __len__(self) -> int:
        return self._total

    def _rebalance(self) -> None:
        # After rebalancing, sizes differ by at most 1, and low is larger or equal.
        # For even total without prefer_high, low has the extra element.
        # For even total with prefer_high, high has the extra element.
        target_low = (self._total + (0 if self.prefer_high else 1)) // 2
        target_high = self._total - target_low

        while self._low_size > target_low:
            val = -heapq.heappop(self._low)
            self._prune_low_top()
            heapq.heappush(self._high, val)
            self._low_size -= 1
            self._high_size += 1

        while self._low_size < target_low:
            val = heapq.heappop(self._high)
            self._prune_high_top()
            heapq.heappush(self._low, -val)
            self._low_size += 1
            self._high_size -= 1

    def _prune_low_top(self) -> None:
        while self._low:
            val = -self._low[0]
            if self._delayed_low.get(val, 0):
                heapq.heappop(self._low)
                self._delayed_low[val] -= 1
                if self._delayed_low[val] == 0:
                    del self._delayed_low[val]
            else:
                break

    def _prune_high_top(self) -> None:
        while self._high:
            val = self._high[0]
            if self._delayed_high.get(val, 0):
                heapq.heappop(self._high)
                self._delayed_high[val] -= 1
                if self._delayed_high[val] == 0:
                    del self._delayed_high[val]
            else:
                break

    def _prune_tops(self) -> None:
        self._prune_low_top()
        self._prune_high_top()
