def to_roman(n):
    if type(n) is not int:
        raise TypeError("n must be an int")
    if n < 1 or n > 3999:
        raise ValueError("n must be between 1 and 3999 inclusive")
    values = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1]
    numerals = ["M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"]
    result = []
    for value, numeral in zip(values, numerals):
        while n >= value:
            result.append(numeral)
            n -= value
    return "".join(result)


def from_roman(s):
    if type(s) is not str:
        raise TypeError("s must be a str")
    if not s:
        raise ValueError("empty string is not a valid Roman numeral")
    total = 0
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c == "M":
            total += 1000
            i += 1
        elif c == "D":
            total += 500
            i += 1
        elif c == "C":
            if i + 1 < n and s[i + 1] == "M":
                total += 900
                i += 2
            elif i + 1 < n and s[i + 1] == "D":
                total += 400
                i += 2
            else:
                total += 100
                i += 1
        elif c == "L":
            total += 50
            i += 1
        elif c == "X":
            if i + 1 < n and s[i + 1] == "C":
                total += 90
                i += 2
            elif i + 1 < n and s[i + 1] == "L":
                total += 40
                i += 2
            else:
                total += 10
                i += 1
        elif c == "V":
