from fractions import Fraction


def evaluate(expr: str):
    if not isinstance(expr, str):
        raise ValueError("Input must be a string")

    tokens = _tokenize(expr)
    parser = _Parser(tokens)
    result = parser.parse_expr()
    if parser.pos != len(tokens):
        raise ValueError("Unexpected token after complete parse")
    return _normalize(result)


def _tokenize(expr: str):
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        ch = expr[i]
        if ch.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(("NUM", expr[i:j]))
            i = j
        elif ch in "+-*/^()":
            tokens.append((ch, ch))
            i += 1
        elif ch in " \t":
            i += 1
        else:
            raise ValueError(f"Invalid character: {ch!r}")
    return tokens


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def _peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def _consume(self, expected_type=None):
        token = self._peek()
        if token is None:
            raise ValueError("Unexpected end of input")
        if expected_type is not None and token[0] != expected_type:
            raise ValueError(f"Expected {expected_type}, got {token[0]}")
        self.pos += 1
        return token

    def parse_expr(self):
        # expr := term (('+' | '-') term)*
        value = self.parse_term()
        while True:
            token = self._peek()
            if token is not None and token[0] in ("+", "-"):
                op = token[0]
                self.pos += 1
                right = self.parse_term()
                if op == "+":
                    value = value + right
                else:
                    value = value - right
            else:
                break
        return value

    def parse_term(self):
        # term := unary (('*' | '/') unary)*
        value = self.parse_unary()
        while True:
            token = self._peek()
            if token is not None and token[0] in ("*", "/"):
                op = token[0]
                self.pos += 1
                right = self.parse_unary()
                if op == "*":
                    value = value * right
                else:
                    value = value / right
            else:
                break
        return value

    def parse_unary(self):
        # unary := '-' unary | power
        token = self._peek()
        if token is not None and token[0] == "-":
            self.pos += 1
            operand = self.parse_unary()
            return -operand
        return self.parse_power()

    def parse_power(self):
        # power := atom ('^' unary)?
        base = self.parse_atom()
        token = self._peek()
        if token is not None and token[0] == "^":
            self.pos += 1
            exponent = self.parse_unary()
            return _power(base, exponent)
        return base

    def parse_atom(self):
        # atom := INTEGER | '(' expr ')'
        token = self._peek()
        if token is None:
            raise ValueError("Unexpected end of input")
        if token[0] == "NUM":
            self.pos += 1
            return Fraction(int(token[1]), 1)
        if token[0] == "(":
            self.pos += 1
            value = self.parse_expr()
            closing = self._peek()
            if closing is None or closing[0] != ")":
                raise ValueError("Missing closing parenthesis")
            self.pos += 1
            return value
        raise ValueError(f"Unexpected token: {token[0]}")


def _power(base: Fraction, exponent: Fraction):
    if exponent.denominator != 1:
        raise ValueError("Exponent must be a whole number")
    exp = exponent.numerator

    if base == 0:
        if exp < 0:
            raise ZeroDivisionError("0 cannot be raised to a negative power")
        if exp == 0:
            return Fraction(1, 1)
        return Fraction(0, 1)

    # Fast exact integer exponentiation over Fractions.
    if exp < 0:
        if base == 0:
            raise ZeroDivisionError("0 cannot be raised to a negative power")
        base = 1 / base
        exp = -exp

    result = Fraction(1, 1)
    while exp > 0:
        if exp % 2 == 1:
            result *= base
        base *= base
        exp //= 2
    return result


def _normalize(value: Fraction):
    if value.denominator == 1:
        return value.numerator
    return value
