import heapq
from typing import List, Tuple


Task = Tuple[int, int, int]
ScheduleItem = Tuple[int, int, int]


def _validate(tasks: List[Task]) -> None:
    for task in tasks:
        if not isinstance(task, tuple) or len(task) != 3:
            raise TypeError("Each task must be a tuple of three ints")
        e, d, p = task
        for value in (e, d, p):
            if isinstance(value, bool) or not isinstance(value, int):
                raise TypeError("enqueue, duration, and priority must be int")
        if e < 0 or d < 0:
            raise ValueError("enqueue and duration must be non-negative")


def schedule(tasks: List[Task]) -> List[ScheduleItem]:
    _validate(tasks)
    n = len(tasks)
    if n == 0:
        return []

    # arrival[t] -> list of task indices arriving at time t, in input order
    # Determine max enqueue to size the arrival buckets.
    max_enqueue = max(task[0] for task in tasks)
    arrivals: List[List[int]] = [[] for _ in range(max_enqueue + 1)]
    for idx, (enqueue, _, _) in enumerate(tasks):
        arrivals[enqueue].append(idx)

    result: List[ScheduleItem] = []
    # priority queue entries: (-priority, duration, index)
    # Python heapq is a min-heap; negate priority for max-priority ordering.
    heap: List[Tuple[int, int, int]] = []
    current_time = 0
    arrived_up_to = -1  # enqueue times <= arrived_up_to have been pushed

    while len(result) < n:
        # Push newly arrived tasks up to current_time.
        if current_time <= max_enqueue:
            for t in range(arrived_up_to + 1, current_time + 1):
                for idx in arrivals[t]:
                    enqueue, duration, priority = tasks[idx]
                    heapq.heappush(heap, (-priority, duration, idx))
            arrived_up_to = current_time
        else:
            # current_time is beyond any future enqueue; ensure all remaining arrivals pushed.
            if arrived_up_to < max_enqueue:
                for t in range(arrived_up_to + 1, max_enqueue + 1):
                    for idx in arrivals[t]:
                        enqueue, duration, priority = tasks[idx]
                        heapq.heappush(heap, (-priority, duration, idx))
                arrived_up_to = max_enqueue

        if not heap:
            # CPU idle: jump to the next enqueue time.
            # Since we may have pushed up to current_time, find next bucket with tasks.
            next_time = current_time + 1
            while next_time <= max_enqueue and not arrivals[next_time]:
                next_time += 1
            if next_time > max_enqueue:
                break  # no more tasks (should not happen if input valid)
            current_time = next_time
            continue

        neg_priority, duration, idx = heapq.heappop(heap)
        start = current_time
        end = start + duration
        result.append((idx, start, end))
        current_time = end

    return result


def waiting_times(tasks: List[Task]) -> List[int]:
    sched = schedule(tasks)
    waits = [0] * len(tasks)
    for idx, start, _ in sched:
        waits[idx] = start - tasks[idx][0]
    return waits
