class Scheduler:
    def __init__(self):
        self._tasks = {}
        self._order_counter = 0
        self._pending = set()
        self._running = set()
        self._completed = set()

    def add(self, name, priority, after=()):
        if name in self._tasks:
            raise ValueError(f"Task {name!r} already added")
        after_tuple = tuple(after)
        for dep in after_tuple:
            if dep not in self._tasks:
                raise KeyError(f"Dependency {dep!r} not found")
        self._order_counter += 1
        self._tasks[name] = {
            "priority": priority,
            "after": after_tuple,
            "order": self._order_counter,
        }
        self._pending.add(name)

    def next(self):
        ready = []
        for name in self._pending:
            deps = self._tasks[name]["after"]
            if all(dep in self._completed for dep in deps):
                ready.append(name)
        if not ready:
            return None
        chosen = max(
            ready,
            key=lambda n: (self._tasks[n]["priority"], -self._tasks[n]["order"]),
        )
        self._pending.remove(chosen)
        self._running.add(chosen)
        return chosen

    def complete(self, name):
        if name not in self._tasks:
            raise KeyError(f"Task {name!r} not found")
        if name not in self._running:
            raise ValueError(f"Task {name!r} is not currently running")
        self._running.remove(name)
        self._completed.add(name)

    def remaining(self):
        return len(self._pending) + len(self._running)
