import re


_VERSION_RE = re.compile(
    r"""
    ^(?i:v)?                              # optional leading v/V
    (?P<major>0|[1-9]\d*)\.
    (?P<minor>0|[1-9]\d*)\.
    (?P<patch>0|[1-9]\d*)
    (?:-(?P<prerelease>[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*))?   # optional prerelease
    (?:\+(?P<build>[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*))?       # optional build
    \Z
    """,
    re.VERBOSE,
)


def _parse_identifier(ident):
    if ident.isdigit():
        if len(ident) > 1 and ident[0] == "0":
            raise ValueError("invalid version: numeric identifier has leading zero")
        return int(ident)
    return ident


def parse_version(text):
    if not isinstance(text, str):
        raise ValueError("invalid version: input must be a string")
    match = _VERSION_RE.match(text)
    if not match:
        raise ValueError("invalid version: malformed version string")
    major = int(match.group("major"))
    minor = int(match.group("minor"))
    patch = int(match.group("patch"))
    prerelease_raw = match.group("prerelease")
    build_raw = match.group("build")
    if prerelease_raw is None:
        prerelease = ()
    else:
        try:
            prerelease = tuple(_parse_identifier(part) for part in prerelease_raw.split("."))
        except ValueError as exc:
            raise ValueError("invalid version: " + str(exc).split(": ", 1)[-1]) from None
    build = build_raw if build_raw is not None else None
    return (major, minor, patch, prerelease, build)


def _compare_prerelease(pre_a, pre_b):
    len_a = len(pre_a)
    len_b = len(pre_b)
    for i in range(min(len_a, len_b)):
        a = pre_a[i]
        b = pre_b[i]
        a_is_int = isinstance(a, int)
        b_is_int = isinstance(b, int)
        if a_is_int and b_is_int:
            if a < b:
                return -1
            if a > b:
                return 1
        elif a_is_int:
            return -1
        elif b_is_int:
            return 1
        else:
            if a < b:
                return -1
            if a > b:
                return 1
    if len_a < len_b:
        return -1
    if len_a > len_b:
        return 1
    return 0


def compare_versions(a, b):
    parsed_a = parse_version(a)
    parsed_b = parse_version(b)
    for field_a, field_b in zip(parsed_a[:3], parsed_b[:3]):
        if field_a < field_b:
            return -1
        if field_a > field_b:
            return 1
    pre_a = parsed_a[3]
    pre_b = parsed_b[3]
    if pre_a and not pre_b:
        return -1
    if not pre_a and pre_b:
        return 1
    cmp = _compare_prerelease(pre_a, pre_b)
    if cmp != 0:
        return cmp
    return 0


def sort_versions(versions):
    return sorted(versions, key=compare_versions)
