import re
from decimal import Decimal, ROUND_HALF_EVEN


class FifoBook:
    _PRICE_RE = re.compile(r'^\d+(?:\.\d{1,4})?$')
    _CENT = Decimal('0.01')

    def __init__(self):
        self._lots = []  # list of [remaining_qty, original_price_str, cost_price]
        self._position = 0
        self._realized = Decimal('0.00')

    def _validate_qty(self, qty):
        if type(qty) is not int:
            raise TypeError("qty must be int")
        if qty <= 0:
            raise ValueError("qty must be positive")

    def _validate_price(self, price):
        if type(price) is not str:
            raise TypeError("price must be str")
        if not self._PRICE_RE.match(price):
            raise ValueError("invalid price format")
        return Decimal(price)

    def buy(self, qty, price):
        self._validate_qty(qty)
        cost = self._validate_price(price)
        self._lots.append([qty, price, cost])
        self._position += qty

    def sell(self, qty, price):
        self._validate_qty(qty)
        sell_price = self._validate_price(price)
        if qty > self._position:
            raise ValueError("insufficient holdings")
        remaining = qty
        pnl = Decimal('0')
        while remaining > 0:
            lot = self._lots[0]
            lot_qty = lot[0]
            if lot_qty <= remaining:
                pnl += (sell_price - lot[2]) * lot_qty
                remaining -= lot_qty
                self._position -= lot_qty
                self._lots.pop(0)
            else:
                pnl += (sell_price - lot[2]) * remaining
                lot[0] -= remaining
                self._position -= remaining
                remaining = 0
        quantized = pnl.quantize(self._CENT, rounding=ROUND_HALF_EVEN)
        self._realized += quantized
        return quantized

    def realized(self):
        return self._realized

    def holdings(self):
        return self._position

    def lots(self):
        return [(lot[0], lot[1]) for lot in self._lots]

    def cost_basis(self):
        total = Decimal('0')
        for lot in self._lots:
            total += lot[2] * lot[0]
        return total.quantize(self._CENT, rounding=ROUND_HALF_EVEN)
