def spans(prices):
    if not isinstance(prices, list):
        raise TypeError("prices must be a list")
    n = len(prices)
    result = [0] * n
    stack = []
    for i in range(n):
        p = prices[i]
        if p is None:
            stack.clear()
            result[i] = 0
            continue
        if isinstance(p, bool) or not isinstance(p, (int, float)):
            raise TypeError("prices must contain int, float or None")
        while stack:
            top_i, top_p = stack[-1]
            if top_p <= p:
                stack.pop()
            else:
                break
        stack.append((i, p))
        span = i - (stack[0][0] if len(stack) > 1 else 0) + 1
        result[i] = span
    return result


def next_greater(prices):
    if not isinstance(prices, list):
        raise TypeError("prices must be a list")
    n = len(prices)
    result = [-1] * n
    stack = []
    for i in range(n - 1, -1, -1):
        p = prices[i]
        if p is None:
            stack.clear()
            result[i] = -1
            continue
        if isinstance(p, bool) or not isinstance(p, (int, float)):
            raise TypeError("prices must contain int, float or None")
        while stack:
            j, jp = stack[-1]
            if jp <= p:
                stack.pop()
            else:
                result[i] = j
                break
        else:
            result[i] = -1
        stack.append((i, p))
    return result


def widest_span(prices):
    span_list = spans(prices)
    best_idx = -1
    best_span = 0
    for i, s in enumerate(span_list):
        if s >= best_span:
            best_span = s
            best_idx = i
    return (best_idx, best_span)
