def _parse_version(version_str):
    s = version_str.strip()
    if not s:
        raise ValueError("empty version")
    parts = s.split('.')
    nums = []
    for part in parts:
        if not part:
            raise ValueError("empty version component")
        if not part.isdigit():
            raise ValueError("non-numeric version component")
        # strip leading zeros is fine; value is numeric
        nums.append(int(part))
    return nums


def _normalize(version_nums):
    # trailing zeros don't matter; return a finite tuple without trailing zeros
    # for comparison, missing components are 0, so we can compare elementwise
    # with 0 default.
    return version_nums


def _compare(a, b):
    # a, b are lists of ints. missing trailing components treated as 0.
    n = max(len(a), len(b))
    for i in range(n):
        av = a[i] if i < len(a) else 0
        bv = b[i] if i < len(b) else 0
        if av != bv:
            return -1 if av < bv else 1
    return 0


def _is_equal(a, b):
    return _compare(a, b) == 0


def _increment_drop_last(version_nums):
    if len(version_nums) < 2:
        raise ValueError("~= requires multi-component version")
    base = version_nums[:-1]
    base[-1] += 1
    return base


def _parse_clause(clause_str):
    s = clause_str.strip()
    if not s:
        raise ValueError("empty clause")
    # find operator prefix
    operators = ('==', '!=', '>=', '<=', '~=', '>', '<')
    op = None
    for candidate in operators:
        if s.startswith(candidate):
            op = candidate
            version_part = s[len(candidate):]
            break
    if op is None:
        raise ValueError("missing operator in clause")
    version_nums = _parse_version(version_part)
    return op, version_nums


def _clause_satisfies(version_nums, op, target_nums):
    if op == '==':
        return _is_equal(version_nums, target_nums)
    if op == '!=':
        return not _is_equal(version_nums, target_nums)
    cmp = _compare(version_nums, target_nums)
    if op == '>=':
        return cmp >= 0
    if op == '<=':
        return cmp <= 0
    if op == '>':
        return cmp > 0
    if op == '<':
        return cmp < 0
    if op == '~=':
        upper = _increment_drop_last(target_nums)
        return _compare(version_nums, target_nums) >= 0 and _compare(version_nums, upper) < 0
    raise ValueError("unknown operator")


def satisfies(version, spec):
    version_nums = _parse_version(version)
    if spec is None or spec.strip() == '':
        return True
    clauses = spec.split(',')
    for clause in clauses:
        op, target_nums = _parse_clause(clause)
        if not _clause_satisfies(version_nums, op, target_nums):
            return False
    return True


def max_satisfying(versions, spec):
    best_original = None
    best_nums = None
    for v in versions:
        nums = _parse_version(v)
        if satisfies(v, spec):
            if best_nums is None or _compare(nums, best_nums) > 0:
                best_original = v
                best_nums = nums
            # if equal, keep first occurrence, do nothing
    return best_original
