def validate_stream(events):
    seen_ids = set()
    for event in events:
        event_id = event[1]
        if event_id in seen_ids:
            raise ValueError(f"duplicate id: {event_id}")
        seen_ids.add(event_id)

    prev = None
    for event in events:
        key = (event[0], event[1])
        if prev is not None and key <= prev:
            raise ValueError(f"unsorted at: {event[1]}")
        prev = key

    return None


def diff_events(old, new):
    validate_stream(old)
    validate_stream(new)

    old_by_id = {event[1]: event for event in old}
    new_by_id = {event[1]: event for event in new}

    old_ids = set(old_by_id)
    new_ids = set(new_by_id)

    added = [event_id for event_id in (event[1] for event in new) if event_id not in old_ids]
    removed = [event_id for event_id in (event[1] for event in old) if event_id not in new_ids]

    common = new_ids & old_ids
    moved = []
    changed = []
    for event in new:
        event_id = event[1]
        if event_id in common:
            old_event = old_by_id[event_id]
            if event[0] != old_event[0]:
                moved.append(event_id)
            if event[2] != old_event[2]:
                changed.append(event_id)

    return {
        "added": added,
        "removed": removed,
        "moved": moved,
        "changed": changed,
    }


def merge_streams(a, b):
    validate_stream(a)
    validate_stream(b)

    a_by_id = {event[1]: event for event in a}
    merged_by_id = dict(a_by_id)

    for event in b:
        merged_by_id[event[1]] = event

    merged = sorted(merged_by_id.values(), key=lambda event: (event[0], event[1]))

    validate_stream(merged)
    return merged
