class CycleError(ValueError):
    def __init__(self, nodes, message="cycle detected"):
        super().__init__(message)
        self.nodes = nodes


def _build_graph(nodes, edges):
    node_set = set(nodes)
    if not all(isinstance(n, str) for n in node_set):
        raise ValueError("all nodes must be strings")

    preds = {n: set() for n in node_set}
    succs = {n: set() for n in node_set}

    for before, after in edges:
        if before not in node_set:
            raise ValueError(f"unknown node: {before}")
        if after not in node_set:
            raise ValueError(f"unknown node: {after}")
        if after not in succs[before]:
            succs[before].add(after)
            preds[after].add(before)

    return node_set, preds, succs


def topo_order(nodes, edges):
    node_set, preds, succs = _build_graph(nodes, edges)

    available = sorted([n for n in node_set if not preds[n]])
    placed = set()
    order = []

    while available:
        node = available.pop(0)
        placed.add(node)
        order.append(node)

        for nxt in sorted(succs[node]):
            preds[nxt].discard(node)
            if not preds[nxt] and nxt not in placed:
                available.append(nxt)
        available.sort()

    if len(order) != len(node_set):
        unplaced = sorted(node_set - placed)
        raise CycleError(unplaced)

    return order


def layers(nodes, edges):
    node_set, preds, succs = _build_graph(nodes, edges)

    remaining_preds = {n: set(preds[n]) for n in node_set}
    placed = set()
    result = []

    while True:
        layer = sorted([n for n in node_set if n not in placed and not remaining_preds[n]])
        if not layer:
            break
        result.append(layer)
        for node in layer:
            placed.add(node)
            for nxt in succs[node]:
                remaining_preds[nxt].discard(node)

    if len(placed) != len(node_set):
        unplaced = sorted(node_set - placed)
        raise CycleError(unplaced)

    return result
